pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint initialDepositsCount;

    function setUp() public {
        c = new C();
        initialDepositsCount = c.depositsCount();
    }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Record the count before calling sendMoney
        uint before = c.depositsCount();

        // Call sendMoney — this will trigger the fallback if target is the contract itself
        // To ensure fallback is triggered, set target to the contract address
        vm.assume(target == address(c));
        // Ensure enough value to do the call
        vm.deal(address(c), value);
        c.sendMoney(target, value, data);

        // After sendMoney, the fallback should have incremented depositsCount
        // For reference C, depositsCount must have increased by exactly 1.
        // For buggy M, depositsCount stays the same (no increment).
        uint after = c.depositsCount();
        assertTrue(after == before + 1, "depositsCount did not increment after sendMoney call that triggers fallback");
    }
}

