pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_target != address(0));
        // Ensure the contract has enough balance for the call
        vm.deal(address(c), _value);
        // Record the initial owner balance
        address owner = c.owner();
        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, _target, _value, _data));
        // The property: calling sendMoney must trigger the fallback (which increments depositsCount) 
        // and then withdrawAll should work (i.e. not revert) because depositsCount > 0 means fallback was called.
        // But in the buggy version, withdrawAll is empty and does not call withdraw, so after sendMoney, 
        // the owner can still call withdrawAll without reverting (since it's empty), but the reference 
        // would revert because fallback was called and depositsCount increased – wait, need to rethink.
        // Actually, the property is about the withdrawAll function's effect, not its revert behavior.
        // Let's check the state: after sendMoney, the contract's balance may change.
        // We assert that calling withdrawAll after sendMoney leaves the contract balance as 0.
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}

