contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Bound _value to avoid excessive gas
        _value = bound(_value, 0, address(c).balance);
        vm.assume(_target != address(0));

        // Record balances before
        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(c.owner()).balance;

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, _target, _value, _data));
        // Only consider successful calls for this rule
        vm.assume(success);

        // Balances after
        uint256 balanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = address(c.owner()).balance;

        // The total amount (contract + owner) must not change because the only way to move ETH is to the owner via withdrawAll, which is now empty
        assertTrue(balanceBefore + ownerBalanceBefore == balanceAfter + ownerBalanceAfter, "Total ETH invariant broken");
    }
}

