pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Restrict inputs: target is not the contract itself, value is at most address(this).balance
        vm.assume(target != address(c));
        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;

        // Record the balance after sendMoney call
        try c.sendMoney(target, value, data) {
            // sendMoney succeeded
            uint256 balanceAfter = address(c).balance;
            // General rule: balance decreased by exactly value if call succeeded
            assertTrue(balanceBefore - balanceAfter == value, "balance change should equal value");
        } catch {
            // sendMoney reverted: note that in reference it can revert due to failed call
            // But the mutant never reverts (it uses transfer(0) which may succeed/fail differently)
            // We simply check that if sendMoney reverts, balance remains unchanged
            assertTrue(address(c).balance == balanceBefore, "balance unchanged on revert");
        }
    }
}

