pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositValue, uint256 sendValue, bytes memory data) public {
        // Ensure sender is the owner (or we can manipulate owner via prank? We'll just assume owner is the contract deployer)
        vm.assume(sender == c.owner());

        // Bound values to avoid overflow issues
        depositValue = bound(depositValue, 1, 1e18);
        sendValue = bound(sendValue, 0, 1e18);

        // Fund the contract with deposit via fallback
        vm.deal(address(this), depositValue);
        (bool success, ) = address(c).call{value: depositValue}("");
        require(success);

        // Record balance before sendMoney
        uint256 balanceBefore = address(c).balance;

        // Call sendMoney as owner
        vm.prank(sender);
        c.sendMoney(address(0x123), sendValue, data);

        // The rule: after sendMoney, call withdrawAll, then the contract balance should be zero
        // because withdrawAll transfers entire balance to owner.
        // The bug (withdraw sends 0) means the balance after withdrawAll will still be non-zero.
        // So we check that after withdrawAll, the contract balance is zero.
        vm.prank(sender);
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}

