import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, uint256 depositValue, bytes memory data) public {
        // Bound depositValue to avoid overflow, and ensure it's reasonable
        vm.assume(depositValue <= 1e18);
        vm.assume(value <= 1e18);

        // Make the owner send some ether to trigger deposits
        vm.deal(address(this), depositValue);
        (bool success, ) = address(c).call{value: depositValue}("");
        require(success, "deposit failed");

        uint256 balanceBefore = address(c).balance;

        // Now call sendMoney as owner
        vm.prank(c.owner());
        c.sendMoney(target, value, data);

        // General rule: if the external call succeeded (no revert), contract balance should decrease by exactly value
        // But if target call reverts, the contract's balance stays the same (value stays in contract)
        // For the reference, it should always hold that after sendMoney, balanceBefore - address(c).balance is either 0 or value (depending on revert)
        // To handle revert, we capture the return value
        // Actually easier: we know that the reference sends value, bug sends 0. So after sendMoney, the difference is value vs 0.
        // But we need a general rule that holds for all inputs.
        // Rule: balanceBefore - address(c).balance equals value if the target.call succeeds and the contract sends that value; otherwise it's 0.
        // Since we can't check revert from the outside easily via try/catch without altering the test, we note that in the reference, the call inside sendMoney uses .call{value: value}(data) which returns a bool, and require(__sent_result100) ensures it reverts on failure.
        // So the only way sendMoney reverts is if the call fails. In that case, balanceBefore - address(c).balance = 0.
        // If it doesn't revert, balanceBefore - address(c).balance = value.
        // This holds for the reference and breaks when bug changes to 0.
        // We can express: (balanceBefore - address(c).balance) == value OR (balanceBefore - address(c).balance) == 0
        // But with fuzz, we need to know which case. Better: use try/catch.
        // Rewrite with try/catch to separate cases.
    }
}

